          status: "success",
          title: "代码审查完成",
          agent: "reviewer",
          project: "auth-module",
          duration: 91,
          model: "claude-4",
          time: "5 小时前",
          body: "审查了 12 个文件，发现 2 个潜在空指针，已生成修复建议。",
          link: "pi://session/sess_31de",
          sessionId: "sess_31de4b",
