				nav.append(el("div", { class: "side-label", text: group.label }));
			const box = el("div", { class: "space-y-1" });
			for (const item of group.items) {
				const a = el("a", {
					href: item.href,
					class: `side-link ${item.id === o.active ? "active" : ""}`,
				});
				a.append(icon(ICONS[item.icon]), item.label);
				box.append(a);
