						"aria-label": "通知",
						onclick: () => (location.href = "index.html#recent"),
					},
					icon(
						["M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9", "M13.73 21a2 2 0 0 1-3.46 0"],
						"h-5 w-5",
					),
					el("span", {
						class: "absolute right-1.5 top-1.5 h-2 w-2 rounded-full bg-red-500",
