/* Anotify · 共享 UI 样式（依赖 tokens.css 提供色彩变量） */

* {
	-webkit-font-smoothing: antialiased;
	-moz-osx-font-smoothing: grayscale;
}
body {
	font-family: "Inter", system-ui, sans-serif;
	background: var(--bg);
	color: var(--text);
	font-feature-settings: "ss01", "cv11", "liga";
}
.font-script {
	font-family: "Sacramento", "Great Vibes", cursive;
}
.font-display {
	font-family: "Fraunces", Georgia, serif;
}
::selection {
	background: rgba(139, 139, 253, 0.35);
	color: #fff;
}
::-webkit-scrollbar {
	width: 8px;
	height: 8px;
}
::-webkit-scrollbar-thumb {
	background: rgba(255, 255, 255, 0.1);
	border-radius: 8px;
}
::-webkit-scrollbar-track {
	background: transparent;
}

.glass {
	background: var(--surface-2);
	border: 1px solid var(--line);
	backdrop-filter: blur(14px);
}
.card {
	background: var(--surface-1);
	border: 1px solid var(--line);
	border-radius: 16px;
	transition: border-color 0.3s ease;
}
.card:hover {
	border-color: var(--line-strong);
}

/* 侧边栏 */
.side-link {
	display: flex;
	align-items: center;
	gap: 0.7rem;
	padding: 0.55rem 0.8rem;
	border-radius: 10px;
	font-size: 0.875rem;
	color: var(--muted);
	border: 1px solid transparent;
	transition: all 0.2s ease;
}
.side-link:hover {
	color: var(--text);
	background: var(--surface-2);
}
.side-link.active {
	color: var(--text);
	background: var(--accent-soft);
	border-color: rgba(139, 139, 253, 0.25);
}
.side-link.active svg {
	color: var(--accent);
}
.side-label {
	font-size: 0.68rem;
	letter-spacing: 0.14em;
	text-transform: uppercase;
	color: var(--faint);
	padding: 0 0.8rem;
	margin-top: 1.4rem;
	margin-bottom: 0.5rem;
	font-weight: 500;
}

/* 状态点 */
.dot {
	width: 8px;
	height: 8px;
	border-radius: 9999px;
	flex-shrink: 0;
}
.dot-success {
	background: var(--success);
	box-shadow: 0 0 8px color-mix(in srgb, var(--success) 60%, transparent);
}
.dot-error {
	background: var(--error);
	box-shadow: 0 0 8px color-mix(in srgb, var(--error) 60%, transparent);
}
.dot-warn {
	background: var(--warn);
	box-shadow: 0 0 8px color-mix(in srgb, var(--warn) 60%, transparent);
}

.kbd {
	font-family: ui-monospace, "SF Mono", Menlo, monospace;
	font-size: 0.66rem;
	border: 1px solid var(--line-strong);
	border-bottom-width: 2px;
	border-radius: 5px;
	padding: 0.05rem 0.35rem;
	color: var(--muted);
	background: var(--surface-1);
}

.btn-primary {
	position: relative;
	background: #fff;
	color: #0a0a10;
	transition: all 0.25s ease;
	box-shadow:
		0 0 0 1px rgba(255, 255, 255, 0.9),
		0 8px 30px -6px rgba(255, 255, 255, 0.2);
	overflow: hidden;
	cursor: pointer;
}
.btn-primary:hover {
	box-shadow:
		0 0 0 1px rgba(255, 255, 255, 1),
		0 12px 40px -6px rgba(139, 139, 253, 0.45);
}
.btn-primary:disabled {
	opacity: 0.55;
	cursor: not-allowed;
}
.btn-ghost {
	border: 1px solid var(--line-strong);
	color: var(--muted);
	transition: all 0.25s ease;
	cursor: pointer;
}
.btn-ghost:hover {
	border-color: rgba(255, 255, 255, 0.35);
	color: var(--text);
	background: var(--surface-1);
}
.btn-danger {
	border: 1px solid rgba(251, 113, 133, 0.25);
	color: var(--error);
	transition: all 0.25s ease;
	cursor: pointer;
}
.btn-danger:hover {
	background: var(--error-soft);
	border-color: rgba(251, 113, 133, 0.5);
}

.badge-dot {
	animation: pulse 2.2s ease-in-out infinite;
}
@keyframes pulse {
	0%,
	100% {
		box-shadow: 0 0 0 0 var(--success-soft);
	}
	50% {
		box-shadow: 0 0 0 5px transparent;
	}
}

/* 状态徽章 */
.status-badge {
	display: inline-flex;
	align-items: center;
	gap: 0.35rem;
	font-size: 0.7rem;
	font-weight: 500;
	padding: 0.15rem 0.6rem;
	border-radius: 9999px;
	white-space: nowrap;
}
.status-success {
	background: var(--success-soft);
	color: #6ee7b7;
}
.status-error {
	background: var(--error-soft);
	color: #fda4af;
}
.status-warn {
	background: var(--warn-soft);
	color: #fcd34d;
}
