    <script>
      (function () {
        "use strict";
        const { el, toast, b64urlToBuf, bufToB64url } = window.Anotify;

        /* ---------- Tab 切换 ---------- */
        const tabLogin = document.getElementById("tab-login");
        const tabSignup = document.getElementById("tab-signup");
        const loginPanel = document.getElementById("login-panel");
        const signupPanel = document.getElementById("signup-panel");
        function switchTab(tab) {
          const isLogin = tab === "login";
          tabLogin.classList.toggle("active", isLogin);
          tabSignup.classList.toggle("active", !isLogin);
          loginPanel.classList.toggle("hidden", !isLogin);
          signupPanel.classList.toggle("hidden", isLogin);
        }
        tabLogin.addEventListener("click", () => switchTab("login"));
        tabSignup.addEventListener("click", () => switchTab("signup"));

        /* ---------- 状态提示 ---------- */
        const statusBox = document.getElementById("status-box");
        function showStatus(msg, kind) {
          statusBox.classList.remove("hidden");
          const map = {
            info: ["var(--accent-soft)", "#b8b8ff"],
            error: ["var(--error-soft)", "#fda4af"],
            success: ["var(--success-soft)", "#6ee7b7"],
            warn: ["var(--warn-soft)", "#fcd34d"],
          };
          const [bg, fg] = map[kind] || map.info;
          statusBox.style.background = bg;
          statusBox.style.color = fg;
          statusBox.textContent = msg;
        }
        function hideStatus() {
          statusBox.classList.add("hidden");
        }

        /* ---------- iOS 提示 ---------- */
        const ua = navigator.userAgent || "";
        const isIOS = /iPhone|iPad|iPod/.test(ua);
        const isStandalone =
          window.matchMedia("(display-mode: standalone)").matches ||
          window.navigator.standalone === true;
        if (isIOS && !isStandalone) {
          document.getElementById("ios-tip").classList.remove("hidden");
        }

        /* ---------- WebAuthn 支持检测 ---------- */
        const webauthnOK =
          window.PublicKeyCredential &&
          navigator.credentials &&
          navigator.credentials.create;

        /* ---------- 后端可用性：失败时进入演示模式 ---------- */
        async function postJSON(url, body) {
          const res = await fetch(url, {
            method: "POST",
            credentials: "include",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(body || {}),
          });
          if (!res.ok) {
            const data = await res.json().catch(() => ({}));
            throw new Error(data.error || "HTTP " + res.status);
          }
          return res.json();
        }

        function demoEnter(name) {
          showStatus("后端未连接，已进入演示模式（数据为示例）。", "warn");
          setTimeout(() => {
            location.href = "index.html?demo=1&u=" + encodeURIComponent(name || "zheng");
          }, 700);
        }

        /* ---------- 登录 ---------- */
        const loginBtn = document.getElementById("login-btn");
        async function doLogin() {
          const username = document.getElementById("username").value.trim();
          hideStatus();
          if (!webauthnOK) {
            showStatus("当前浏览器不支持 Passkey（WebAuthn），请换用 Safari / Chrome 最新版。", "error");
            return;
          }
          loginBtn.disabled = true;
          try {
            // 1. 取登录 challenge
            const opts = await postJSON("/v1/auth/login/options", { username });
            const publicKey = opts.publicKey || opts;
            publicKey.challenge = b64urlToBuf(publicKey.challenge);
            if (publicKey.allowCredentials) {
              publicKey.allowCredentials = publicKey.allowCredentials.map((c) => ({
                ...c,
                id: b64urlToBuf(c.id),
              }));
            }
            // 2. 调起认证器
            const assertion = await navigator.credentials.get({ publicKey });
            // 3. 完成登录
            const payload = {
              username,
              id: assertion.id,
              rawId: bufToB64url(assertion.rawId),
              type: assertion.type,
              response: {
                clientDataJSON: bufToB64url(assertion.response.clientDataJSON),
                authenticatorData: bufToB64url(assertion.response.authenticatorData),
                signature: bufToB64url(assertion.response.signature),
                userHandle: assertion.response.userHandle
                  ? bufToB64url(assertion.response.userHandle)
                  : null,
              },
            };
            await postJSON("/v1/auth/login", payload);
            showStatus("登录成功，正在进入工作台…", "success");
            setTimeout(() => (location.href = "index.html"), 500);
          } catch (e) {
            if (String(e).includes("HTTP") || String(e).includes("Failed to fetch")) {
              demoEnter(username || "zheng");
            } else if (e && e.name === "NotAllowedError") {
              showStatus("已取消或超时——请重试并允许使用 Passkey。", "warn");
            } else {
              showStatus("登录失败：" + (e.message || e), "error");
            }
          } finally {
            loginBtn.disabled = false;
          }
        }
        loginBtn.addEventListener("click", doLogin);

        /* ---------- 注册 ---------- */
        const signupBtn = document.getElementById("signup-btn");
        async function doSignup() {
          const username = document.getElementById("new-username").value.trim();
          hideStatus();
          if (!username) {
            document.getElementById("new-username").focus();
            showStatus("先给自己起个用户名。", "warn");
            return;
          }
          if (!webauthnOK) {
            showStatus("当前浏览器不支持 Passkey（WebAuthn），请换用 Safari / Chrome 最新版。", "error");
            return;
          }
          signupBtn.disabled = true;
          try {
            const opts = await postJSON("/v1/auth/register/options", {
              username,
              displayName: username,
            });
            const publicKey = opts.publicKey || opts;
            publicKey.challenge = b64urlToBuf(publicKey.challenge);
            if (publicKey.user && publicKey.user.id)
              publicKey.user.id = b64urlToBuf(publicKey.user.id);
            if (publicKey.excludeCredentials) {
              publicKey.excludeCredentials = publicKey.excludeCredentials.map((c) => ({
                ...c,
                id: b64urlToBuf(c.id),
              }));
            }
            const cred = await navigator.credentials.create({ publicKey });
            const payload = {
              username,
              id: cred.id,
              rawId: bufToB64url(cred.rawId),
              type: cred.type,
              response: {
                clientDataJSON: bufToB64url(cred.response.clientDataJSON),
                attestationObject: bufToB64url(cred.response.attestationObject),
              },
            };
            await postJSON("/v1/auth/register", payload);
            showStatus("注册成功！正在进入工作台…", "success");
            setTimeout(() => (location.href = "index.html"), 600);
          } catch (e) {
            if (String(e).includes("HTTP") || String(e).includes("Failed to fetch")) {
              demoEnter(username);
            } else if (e && e.name === "NotAllowedError") {
              showStatus("已取消或超时——请重试并允许创建 Passkey。", "warn");
            } else {
              showStatus("注册失败：" + (e.message || e), "error");
            }
          } finally {
            signupBtn.disabled = false;
          }
        }
        signupBtn.addEventListener("click", doSignup);

        /* ---------- 恢复码入口 ---------- */
        document.getElementById("recovery-btn").addEventListener("click", () => {
          toast("恢复码登录将在后端接入后开放（用户名 + 一次性恢复码）", "warn");
        });

        /* ---------- 回车提交 ---------- */
        window.addEventListener("keydown", (e) => {
          if (e.key !== "Enter") return;
          if (!signupPanel.classList.contains("hidden")) doSignup();
          else doLogin();
        });
      })();
    </script>
  </body>
</html>
