// T13 验证脚本：无头 Chrome 打开三个页面，收集 console/pageerror/失败请求/溢出，并截图
import { chromium } from "playwright-core";
import fs from "node:fs";

const BASE = "http://localhost:5712";
const pages = [
	["login.html", "登录"],
	["index.html", "总览"],
	["receivers.html", "通知接收"],
];
const shotDir = "/tmp/t13-shots";
fs.mkdirSync(shotDir, { recursive: true });

const browser = await chromium.launch({ channel: "chrome", headless: true, args: ["--no-sandbox"] });
let fail = 0;

for (const [file, name] of pages) {
	const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
	const consoleErrors = [];
	const pageErrors = [];
	const failedReq = [];
	page.on("console", (m) => m.type() === "error" && consoleErrors.push(m.text()));
	page.on("pageerror", (e) => pageErrors.push(String(e)));
	page.on("requestfailed", (r) => failedReq.push(`${r.method()} ${r.url()} → ${r.failure()?.errorText}`));

	const resp = await page.goto(`${BASE}/${file}`, { waitUntil: "load", timeout: 20000 });
	await page.waitForTimeout(1800);

	// 滚动到底
	const scrollH = await page.evaluate(() => document.documentElement.scrollHeight);
	await page.evaluate(() => window.scrollTo(0, document.documentElement.scrollHeight));
	await page.waitForTimeout(400);
	const bottomY = await page.evaluate(() => window.scrollY);
	const maxY = scrollH - 800;
	const scrollOK = scrollH <= 800 || bottomY >= maxY - 5;

	// 溢出检测
	const overflow = await page.evaluate(() => {
		const out = [];
		const vw = window.innerWidth;
		for (const el of document.querySelectorAll("body *")) {
			const r = el.getBoundingClientRect();
			if (r.right > vw + 5 && !el.closest("pre") && !el.closest(".overflow-x-auto") && !el.closest("#hm")) {
				out.push(`${el.tagName}.${(el.className || "").toString().slice(0, 40)} right=${Math.round(r.right)}`);
			}
		}
		return out.slice(0, 6);
	});

	await page.evaluate(() => window.scrollTo(0, 0));
	await page.waitForTimeout(300);
	const shot = `${shotDir}/${file.replace(".html", "")}.png`;
	await page.screenshot({ path: shot, fullPage: true });

	// 过滤：后端 /v1/* 与 manifest/sw 在本静态服务下预期失败（联调期才会有）
	const infra = (u) => u.includes("/v1/") || u.includes("manifest.webmanifest") || u.includes("sw.js");
	const realConsole = consoleErrors.filter((c) => !infra(c));
	const realPageErr = pageErrors.filter((c) => !infra(c));
	const realFailed = failedReq.filter((u) => !infra(u));

	const problems = [];
	if (resp.status() >= 400) problems.push(`HTTP ${resp.status()}`);
	if (!scrollOK) problems.push(`无法滚动到底 (${Math.round(bottomY)}/${Math.round(maxY)})`);
	problems.push(...realConsole.map((c) => "console: " + c));
	problems.push(...realPageErr.map((c) => "pageerror: " + c));
	problems.push(...realFailed.map((c) => "reqfail: " + c));
	problems.push(...overflow.map((c) => "overflow: " + c));

	const status = problems.length === 0 ? "✅ PASS" : "❌ FAIL";
	if (problems.length) fail++;
	console.log(`\n== ${name} (${file}) → ${status} · 截图 ${shot}`);
	console.log(`   title=${await page.title()} · scrollH=${scrollH}`);
	for (const p of problems) console.log("   ⚠️ " + p);
	if (failedReq.length !== realFailed.length)
		console.log(`   （已忽略 ${failedReq.length - realFailed.length} 个预期内的 /v1/* 请求失败——后端未起）`);

	// 移动端视口复测（溢出）
	const mp = await browser.newPage({ viewport: { width: 390, height: 844 } });
	const mErr = [];
	mp.on("pageerror", (e) => mErr.push(String(e)));
	await mp.goto(`${BASE}/${file}`, { waitUntil: "load", timeout: 20000 });
	await mp.waitForTimeout(1200);
	const mOverflow = await mp.evaluate(() => {
		const out = [];
		const vw = window.innerWidth;
		for (const el of document.querySelectorAll("body *")) {
			const r = el.getBoundingClientRect();
			if (r.right > vw + 5 && !el.closest("pre") && !el.closest(".overflow-x-auto") && !el.closest("#hm")) {
				out.push(`${el.tagName}.${(el.className || "").toString().slice(0, 40)} right=${Math.round(r.right)}`);
			}
		}
		return out.slice(0, 5);
	});
	await mp.screenshot({ path: `${shotDir}/${file.replace(".html", "")}-mobile.png`, fullPage: true });
	if (mOverflow.length) {
		fail++;
		console.log(`   移动端(390px) 溢出: ❌`);
		mOverflow.forEach((o) => console.log("   ⚠️ m-overflow: " + o));
	} else {
		console.log(`   移动端(390px) 溢出: ✅ 无`);
	}
	await mp.close();
	await page.close();
}

await browser.close();
console.log(`\n===== 结果：${fail === 0 ? "全部通过 ✅" : fail + " 项失败 ❌"} =====`);
process.exit(fail === 0 ? 0 : 1);

